 'use client';

 // ══════════════════════════════════════════════════════════════
 // 학생: 학원 조교 질문 작성 + 내 질문/답변(사진·영상) 확인.
 // ══════════════════════════════════════════════════════════════
 import { useCallback, useEffect, useState } from 'react';
 import { uploadTaFile } from '@/lib/ta-upload-client';
 import { useBrand } from '@/components/brand/useBrand';
+import WrongNotesSummaryCard from '@/components/questions/WrongNotesSummaryCard';
 import type { QuestionsPrefill } from '@/lib/questions-prefill';

 interface Answer {
   id: string;
   answer_text: string | null;
   file_display_url: string | null;
   file_type: 'image' | 'video' | 'file' | null;
   created_at: string;
 }
 interface Question {
   id: string;
   subject: string | null;
   unit: string | null;
   question_text: string;
   image_display_url: string | null;
   status: 'open' | 'answered' | 'closed';
   created_at: string;
   answered_at: string | null;
   answers: Answer[];
 }

 const SUBJECTS = ['국어', '수학', '영어', '탐구', '한국사'];

 export default function QuestionsClient({
   hasAcademy,
   embedded = false,
   initialPrefill,
 }: {
   hasAcademy: boolean;
   /** #548 질문 탭 허브 — true면 자체 컨테이너·h1 없이 섹션으로 렌더(허브 레이아웃에 삽입). */
   embedded?: boolean;
   initialPrefill: QuestionsPrefill;
 }) {
   const brand = useBrand();
   const [questions, setQuestions] = useState<Question[] | null>(null);

   const load = useCallback(async () => {
     try {
       // 답변은 조교의 별도 세션에서 갱신된다. 학생 쪽 mutation만으로는 캐시를 무효화할 수
       // 없으므로 이 목록은 탭 진입마다 서버에서 최신 상태를 읽는다.
       const r = await fetch('/api/questions', { cache: 'no-store' });
       if (!r.ok) throw new Error('질문 목록 조회 실패');
       const j = await r.json();
       setQuestions(Array.isArray(j.questions) ? j.questions : []);
     } catch {
       setQuestions([]);
     }
   }, []);

   useEffect(() => {
     load();
   }, [load]);

   // #548: 허브 임베드 모드 — 컨테이너·헤딩 레벨만 다르고 기능(AskForm·목록·상세)은 동일.
   const Heading = embedded ? 'h2' : 'h1';
   return (
     <div className={embedded ? '' : 'mx-auto max-w-2xl px-4 py-6'}>
       <Heading className={embedded ? 'text-sm font-bold text-slate-900' : 'text-2xl font-black text-slate-900'}>
         학원 조교에게 질문
       </Heading>
       <p className="mt-1 text-sm text-slate-500">
         {brand.coach}로도 이해가 안 되면 학원 조교에게 직접 물어보세요. 조교가 풀이를 사진·영상으로 보내드립니다.
       </p>

       {!hasAcademy ? (
         <div className="mt-6 rounded-2xl border border-slate-200 bg-white p-6 text-center text-sm text-slate-500">
           소속 학원이 등록되어야 조교 질문을 사용할 수 있어요. MY → 학원에서 학원을 먼저 선택하세요.
         </div>
       ) : (
         <AskForm
           onAsked={load}
           initialSubject={initialPrefill.subject}
           tutorSessionId={initialPrefill.session}
           initialImageUrl={initialPrefill.image}
           initialImageDisplayUrl={initialPrefill.imageDisplay}
         />
       )}

       <h2 className="mt-8 text-sm font-bold text-slate-900">내 질문</h2>
       {questions === null ? (
         <p className="mt-3 text-sm text-slate-500">불러오는 중…</p>
       ) : questions.length === 0 ? (
         <p className="mt-3 text-sm text-slate-400">아직 한 질문이 없습니다.</p>
       ) : (
         <div className="mt-3 space-y-2">
           {questions.map((q) => (
             <QuestionItem key={q.id} q={q} />
           ))}
         </div>
       )}
+
+      {/* #748: 조교 답변의 "오답노트에 기록 →"이 실제로 쌓인 결과를 같은 패널에서 확인시킨다.
+          좌측 WrongNotesSidebar(코치+직접 기록 병합, 코치 브릿지용)와 달리 여기는 직접 기록분
+          미리보기 + 정본(/questions/review) 진입점이다. */}
+      <div className="mt-8">
+        <WrongNotesSummaryCard />
+      </div>
     </div>
   );
 }

 function AskForm({
   onAsked,
   initialSubject,
   tutorSessionId,
   initialImageUrl,
   initialImageDisplayUrl,
 }: {
   onAsked: () => void;
   initialSubject?: string | null;
   tutorSessionId?: string | null;
   initialImageUrl?: string | null;
   initialImageDisplayUrl?: string | null;
 }) {
   const [subject, setSubject] = useState(
     initialSubject && SUBJECTS.includes(initialSubject) ? initialSubject : '수학'
   );
   const [text, setText] = useState('');
   const [file, setFile] = useState<File | null>(null);
   const [sending, setSending] = useState(false);
   const [msg, setMsg] = useState<string | null>(null);

   async function submit() {
     if (!text.trim()) {
       setMsg('질문 내용을 입력하세요.');
       return;
     }
     setSending(true);
     setMsg(null);
     try {
       // 직접 첨부한 파일이 우선, 없으면 /tutor에서 넘어온 문제 사진을 자동 첨부
       let imageUrl: string | null = initialImageUrl || null;
       if (file) imageUrl = (await uploadTaFile(file)).url;
       const r = await fetch('/api/questions', {
         method: 'POST',
         headers: { 'Content-Type': 'application/json' },
         body: JSON.stringify({
           question_text: text.trim(),
           subject,
           image_url: imageUrl,
           tutor_session_id: tutorSessionId || null,
         }),
       });
       if (!r.ok) {
         const j = await r.json().catch(() => ({}));
         throw new Error(j.error || '등록 실패');
       }
       setText('');
       setFile(null);
       setMsg('질문을 보냈습니다. 조교가 답변하면 알림이 옵니다.');
       onAsked();
     } catch (e) {
       setMsg(e instanceof Error ? e.message : '등록 실패');
     } finally {
       setSending(false);
     }
   }

   return (
     <div className="mt-5 rounded-2xl border border-slate-200 bg-white p-5">
       <div className="mb-2 flex flex-wrap gap-1.5">
         {SUBJECTS.map((s) => (
           <button
             key={s}
             onClick={() => setSubject(s)}
             className={`rounded-full px-2.5 py-1 text-xs ${subject === s ? 'bg-slate-900 text-white' : 'border border-slate-200 text-slate-600'}`}
           >
             {s}
           </button>
         ))}
       </div>
       <textarea
         value={text}
         onChange={(e) => setText(e.target.value)}
         rows={3}
         placeholder="어디서 막혔는지, 무엇이 이해 안 되는지 적어주세요."
         className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none"
