   166	async function cachedFetchForCurrentSession(
   167	  url: string,
   168	  opts: { ttlMs: number },
   169	  transitionRetries: number,
   170	): Promise<Response> {
   171	  // storage가 막혀도 현재 세션 확인은 생략할 수 없다. cache/dedup만 우회하고, fetch 전후
   172	  // namespace 검증은 항상 수행해 A 응답을 B에게 반환하는 경로를 차단한다.
   173	  const namespace = await currentCacheNamespace();
   174	  const s = storage();
   175	  const key = namespace ? scopedKey(namespace, url) : null;
   176	  if (s && namespace) {
   177	    try {
   178	      s.setItem('cf-uid', namespace);
   179	    } catch {
   180	      /* namespace 기록 실패 시에도 scoped cache key 자체가 사용자 경계를 유지한다. */
   181	    }
   182	  }
   183	  const now = Date.now();
   184	
   185	  if (s && key && namespace) {
   186	    const raw = readStorageItem(s, key);
   187	    if (raw) {
   188	      try {
   189	        const e = JSON.parse(raw) as Entry;
   190	        if (now - e.ts < opts.ttlMs) {
   191	          // A namespace를 읽은 뒤 B로 세션이 바뀌면 A의 캐시 응답도 B에게 반환하지 않는다.
   192	          // cache hit 역시 현재 인증 경계를 다시 확인하지 못하면 공유 캐시를 우회한다.
   193	          if (await isCurrentNamespace(namespace)) {
   194	            return new Response(e.body, {
   195	              status: e.status,
   196	              headers: { 'content-type': 'application/json' },
   197	            });
   198	          }
   199	          return retryForCurrentSession(url, opts, transitionRetries);
   200	        }
   201	      } catch {
   202	        /* 손상된 캐시 항목 무시 → 새로 fetch */
   203	      }
   204	    }
   205	  }
   206	
   207	  // 인증 사용자를 판별하지 못하면 private 응답을 어떤 계정에도 반환할 수 없다. storage 실패는
   208	  // 여기와 무관하다. getSession 검증만 실패한 경우에만 fail-closed 한다.
   209	  if (!namespace) throw new CacheSessionTransitionError();
