   215	  }
   216	
   217	  // sessionStorage가 없으면 cache와 in-flight dedup 모두 우회한다. 단, 아래 fetch 전후
   218	  // namespace 검증은 그대로라 storage 비가용 환경도 계정 경계는 동일하게 보장한다.
   219	  const requestKey = s ? scopedKey(namespace, url) : null;
   220	  let entry = requestKey ? inflight.get(requestKey) : undefined;
   221	  if (!entry) {
   222	    entry = {
   223	      response: fetch(url, { cache: 'no-store' }),
   224	      valid: true,
   225	    };
