    16	async function findStudentId(userId: string): Promise<string> {
    17	  const { data } = await supabaseAdmin
    18	    .from('students')
    19	    .select('id')
    20	    .eq('user_id', userId)
    21	    .maybeSingle();
    22	  if (!data) throw new AuthError(404, '학생 프로필이 없습니다');
    23	  return data.id;
    24	}
