    28	    const user = await requireUser();
    29	    const studentId = await findStudentId(user.id);
    30	    const { data } = await supabaseAdmin
    31	      .from('wrong_notes')
    32	      .select('id, subject, unit, reason, memo, created_at')
    33	      .eq('student_id', studentId)
    34	      .order('created_at', { ascending: false })
    35	      .limit(MANUAL_REVIEW_WINDOW);
