    42	const PostSchema = z.object({
    43	  subject: z.string().min(1).max(30),
    44	  unit: z.string().min(1).max(60),
    45	  reason: z.enum(['concept', 'mistake', 'time']),
    46	  // 교재 출처 마커까지 인코딩된 최종 저장 문자열 기준.
    47	  memo: z.string().max(MAX_WRONG_NOTE_MEMO_LENGTH).optional(),
    48	});
