    50	export async function POST(req: NextRequest) {
    51	  try {
    52	    const user = await requireUser();
    53	    const studentId = await findStudentId(user.id);
    54	    const parsed = PostSchema.safeParse(await req.json());
    55	    if (!parsed.success) {
    56	      if (parsed.error.issues.some((issue) => issue.path[0] === 'memo' && issue.code === 'too_big')) {
    57	        return NextResponse.json(
