'use client';

// ══════════════════════════════════════════════════════════════
// components/questions/WrongNotesSummaryCard.tsx — 오답노트 요약 (M4.7 #548, EP-57)
//
// 질문 탭 우측: 최근 오답(과목 필터) 미리보기 + 전체 보기(/questions/review — 이관 정본).
// 데이터: GET /api/wrong-notes (최신순). 코치 풀이 열람 시 자동 적재분 포함.
// ══════════════════════════════════════════════════════════════
import { useCallback, useEffect, useMemo, useState } from 'react';
import { cachedFetch, invalidateCached } from '@/lib/client-cache';
import { subjectTone } from '@/lib/subject-colors';
import SubjectIcon from '@/components/ui/SubjectIcon';
import { REASON_LABEL } from '@/components/questions/reason-label';
import { decodeMemo } from '@/components/questions/wrongnote-source';
import WrongNotesLoadError from '@/components/questions/WrongNotesLoadError';

interface WrongNote {
  id: string;
  subject: string;
  unit: string;
  reason: string | null;
  memo: string | null;
  created_at: string;
}

export default function WrongNotesSummaryCard() {
  const [notes, setNotes] = useState<WrongNote[] | null>(null);
  const [loadError, setLoadError] = useState(false);
  const [subject, setSubject] = useState<string>('전체');

  const load = useCallback(async () => {
    setLoadError(false);
    try {
      // 읽기 전용 요약 — 탭 진입마다 재로딩하지 않도록 10분 TTL 캐시. 오답 추가는
      // ReviewClient(직접 기록)에서 일어나고 거기서 invalidateCached('/api/wrong-notes')를
      // 호출하므로(sessionStorage 공유), 새 오답이 이 요약에도 즉시 반영된다(스테일 방지).
      const res = await cachedFetch('/api/wrong-notes', { ttlMs: 10 * 60_000 });
      if (!res.ok) throw new Error('wrong-notes fetch failed');
      const j = await res.json();
      if (!Array.isArray(j.notes)) throw new Error('wrong-notes response malformed');
      setNotes(j.notes);
    } catch {
      // 실패를 빈 목록으로 바꾸지 않는다. 그래야 장애가 "기록 없음"으로 오인되지 않는다.
      setLoadError(true);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const retry = useCallback(() => {
    invalidateCached('/api/wrong-notes');
    setNotes(null);
    void load();
  }, [load]);

  const subjects = useMemo(() => {
    const s = new Set((notes ?? []).map((n) => n.subject));
    return ['전체', ...s];
  }, [notes]);

  const filtered = useMemo(
    () => (notes ?? []).filter((n) => subject === '전체' || n.subject === subject).slice(0, 4),
    [notes, subject],
  );

  return (
    <div className="rounded-2xl border border-slate-200 bg-white p-5">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-1.5">
          <h2 className="text-sm font-bold text-slate-900">오답노트</h2>
          {/* 코치→조교의 결과가 여기 쌓인다는 흐름을 라벨로 명시(P1 정보 위계) */}
          <span className="rounded-full bg-rose-50 px-1.5 py-0.5 text-[10px] font-bold text-rose-600">← 결과가 쌓여요</span>
        </div>
        <a href="/questions/review" className="text-xs font-semibold text-blue-700 hover:underline">
          전체 보기 →
        </a>
      </div>
      <p className="mt-1 text-xs text-slate-500">
        직접 기록한 오답이 여기 모여요(코치·조교 자동 오답 포함 전체는 “전체 보기”에서).
        누적 단원은 다음 계획에 약점으로 반영돼요.
      </p>

      {/* 과목 필터 */}
      {subjects.length > 1 && (
        <div className="mt-3 flex flex-wrap gap-1.5">
          {subjects.map((s) => (
            <button
              key={s}
              type="button"
              onClick={() => setSubject(s)}
              className={`rounded-full px-2.5 py-1 text-[11px] font-bold transition ${
                subject === s
                  ? 'bg-blue-600 text-white'
                  : 'bg-slate-50 text-slate-500 hover:bg-slate-100'
              }`}
            >
              {s}
            </button>
          ))}
        </div>
      )}

      {loadError ? (
        <WrongNotesLoadError onRetry={retry} compact />
      ) : notes === null ? (
        <p className="mt-3 text-xs text-slate-400">불러오는 중…</p>
      ) : filtered.length === 0 ? (
        <p className="mt-3 rounded-lg bg-slate-50 px-3 py-3 text-center text-xs text-slate-500">
          아직 기록된 오답이 없어요.
        </p>
      ) : (
        <ul className="mt-3 space-y-2">
          {filtered.map((n) => (
            <li key={n.id}>
              <a
                href={`/questions/review?open=${encodeURIComponent(n.id)}&src=manual`}
                style={{ borderLeft: `3px solid ${subjectTone(n.subject).main}` }}
                className="block rounded-lg border border-slate-100 px-3 py-2 transition hover:border-blue-200 hover:bg-blue-50/40"
              >
                <div className="flex items-center gap-2 text-xs">
                  <span
                    className="inline-flex shrink-0 items-center gap-1 rounded px-1.5 py-0.5 font-bold"
                    style={{ backgroundColor: subjectTone(n.subject).soft, color: subjectTone(n.subject).main }}
                  >
                    <SubjectIcon subject={n.subject} size={12} color={subjectTone(n.subject).main} /> {n.subject}
                  </span>
                  <span className="min-w-0 flex-1 truncate font-semibold text-slate-700">
                    {n.unit}
                  </span>
                  <span className="shrink-0 tabular-nums text-slate-400">
                    {n.created_at.slice(5, 10).replace('-', '/')}
                  </span>
                </div>
                {(() => {
                  // 원시 enum("concept") 직노출 금지 — 오답유형 라벨 우선, 없으면 memo를
                  // decodeMemo로 〔교재:…〕 마커를 떼어낸 본문만 노출(P0/P2 가드레일).
                  const label = n.reason ? REASON_LABEL[n.reason] ?? null : null;
                  const memoText = decodeMemo(n.memo).text.trim();
                  const caption = label
                    ? `${label}${memoText ? ' · 메모 있음' : ''}`
                    : memoText;
                  return caption ? (
                    <p className="mt-1 truncate text-[11px] text-slate-500">{caption}</p>
                  ) : null;
                })()}
              </a>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

