 69	  if (idx >= 0) return ELECTIVE_TONES[idx % ELECTIVE_TONES.length];
 70	  let h = 0;
 71	  for (let i = 0; i < canon.length; i++) h = (h * 31 + canon.charCodeAt(i)) >>> 0;
 72	  return ELECTIVE_TONES[h % ELECTIVE_TONES.length];
 73	}
 74	
 75	export function subjectTone(subject: string): SubjectTone {
 76	  if (NON_STUDY_RE.test(subject)) return FALLBACK;
 77	  for (const [re, tone] of SUBJECT_TONES) {
 78	    if (re.test(subject)) return tone;
 79	  }
 80	  // 탐구·선택 등 나머지 학습 과목은 과목별 순환 색.
 81	  return electiveTone(subject);
 82	}
