 84	// 세부 단원·강의명이 섞인 원본 과목 문자열을 대과목 라벨로 정규화한다.
 85	// (예: "수학(미적분)", "수학(공통수학)", "대성마이맥 미적분 개념완성 강의" → 모두 "수학")
 86	// 과목별 집계(주간/월간 다이제스트 등)에서 같은 과목이 여러 갈래로 쪼개지는 것을 막는다.
 87	// 첫 매칭 우선 — 탐구2·사회를 일반 '탐구'보다 먼저 검사(부분 포함 순서 주의).
 88	// 탐구 선택과목(생명과학·지구과학 등)은 학생마다 여러 개라 과목별로 유지한다(합치지 않음).
 89	const SUBJECT_BASE: Array<[RegExp, string]> = [
 90	  [/국어|문학|독서|화법|언매|비문학/, '국어'],
 91	  [/영어|영독|영작|영문/, '영어'],
 92	  [/수학|미적|확통|기하|수1|수2|수열|극한/, '수학'],
 93	  [/한국사/, '한국사'],
 94	  [/생명|생물/, '생명과학'],
 95	  [/물리/, '물리'],
 96	  [/화학/, '화학'],
 97	  [/지구/, '지구과학'],
 98	  [/사회|생윤|윤사|윤리|정법|정치|경제|사문|지리|한지|세계사|동아시아사|역사|사탐|탐구2/, '사회탐구'],
 99	  [/탐구1|과탐|과학/, '과학탐구'],
100	  [/탐구/, '탐구'],
101	];
