103	/**
104	 * 계획 생성기가 탐구 과제를 찍는 슬롯 라벨('탐구1'/'탐구2')을, 학생이 고른 실제 탐구 과목명
105	 * (science_subject_1/2, 예: '생명과학I')으로 되돌린다. 해당 과목이 없으면 원본을 유지한다.
106	 * baseSubject보다 먼저 적용하면 '탐구1'(생명과학I)이 대과목 '생명과학'으로 정규화돼
107	 * 같은 과목의 다른 행과 자연스럽게 합쳐진다.
108	 */
109	export function resolveSlotSubject(
110	  subject: string,
111	  sci1?: string | null,
112	  sci2?: string | null,
113	): string {
114	  if (subject === '탐구1' && sci1) return sci1;
115	  if (subject === '탐구2' && sci2) return sci2;
116	  return subject;
117	}
118	
119	/**
120	 * 국어·수학·영어·탐구1·탐구2 캐노니컬 표시 순서(M4.7 리포트 탭 감사 — "수학·국어·영어·탐구1"처럼
121	 * 뒤섞여 보이던 문제). 탐구 슬롯은 sci1/sci2로 해석해 실제 과목명이 있으면 그 이름으로,
122	 * 없으면(레거시/미설정) '탐구1'/'탐구2' 그대로 반환 — resolveSlotSubject와 동일한 안전 폴백.
123	 */
124	export function canonicalSubjectOrder(sci1?: string | null, sci2?: string | null): string[] {
125	  return [
126	    '국어',
127	    '수학',
128	    '영어',
129	    resolveSlotSubject('탐구1', sci1, sci2),
130	    resolveSlotSubject('탐구2', sci1, sci2),
131	  ];
132	}
133	
134	/**
135	 * 라벨을 canonicalSubjectOrder 안에서의 인덱스로 변환(정렬용). 국어·수학은 선택과목이 붙어
136	 * "국어(언어와 매체)"처럼 나올 수 있어 접두 매칭도 허용한다. 순서 밖 과목(한국사 등)이나
137	 * 스냅샷이 현재 프로필과 달라 매칭 실패한 탐구 과목은 배열 길이(맨 뒤)로 보내 기존 정렬
138	 * 기준(예: 계획 개수·시간 내림차순)에 맡긴다.
139	 */
140	export function subjectOrderIndex(label: string, order: string[]): number {
141	  const idx = order.findIndex((c) => label === c || label.startsWith(`${c}(`));
142	  return idx === -1 ? order.length : idx;
143	}
