145	/** 원본 과목 문자열 → 대과목 라벨. 매칭 실패 시 원본을 그대로 반환한다(식사·휴식 등 비학습 보존). */
146	export function baseSubject(subject: string): string {
147	  // 탐구 슬롯은 사탐·과탐 어느 쪽도 될 수 있어 프로필 없이 계열을 추정하지 않는다.
148	  if (subject === '탐구1' || subject === '탐구2') return subject;
149	  for (const [re, label] of SUBJECT_BASE) {
150	    if (re.test(subject)) return label;
151	  }
152	  return subject;
153	}
