165	/** TaskCard 처럼 {dot,text} 형태가 필요한 경우 */
166	export function subjectDotText(subject: string): { dot: string; text: string } {
167	  const t = subjectTone(subject);
168	  return { dot: t.soft, text: t.main };
169	}
