172	// 키워드 매칭(위에서부터 우선). 비학습(식사·휴식·기타)도 포함해 스케줄 어디서든 재사용.
173	const SUBJECT_EMOJIS: Array<[RegExp, string]> = [
174	  [/국어|문학|독서|화법|언매|비문학/, '📖'],
175	  [/수학|미적|확통|기하|수1|수2/, '📐'],
