190	/** 과목 이모지(없으면 학습 기본 ✏️). 스케줄·지표·리본에서 과목 시각 구분에 사용. */
191	export function subjectEmoji(subject: string): string {
192	  for (const [re, e] of SUBJECT_EMOJIS) {
193	    if (re.test(subject)) return e;
194	  }
